#!/usr/bin/env node
// Generates src/design/tokens.generated.ts and src/design/art.generated.ts from the
// design-system sources in design-system/. These two generated files are the only places in
// the app where colour literals may appear (DECISIONS §7.7, lint-enforced).
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'design-system/tokens.json'), 'utf8'));
const art = JSON.parse(readFileSync(join(root, 'design-system/art.json'), 'utf8'));

const px = (v) => {
  const m = String(v).match(/^(-?[\d.]+)px$/);
  if (!m) throw new Error(`not a px value: ${v}`);
  return Number(m[1]);
};

// ---------------------------------------------------------------- colours
const raw = new Map(tokens.color.tokens.map((t) => [t.name, t.value]));
const themes = tokens.color.themes.map((t) => t.id);
if (themes.join(',') !== 'light,dark') throw new Error(`unexpected themes ${themes}`);

function resolve(name, theme, seen = new Set()) {
  if (seen.has(name)) throw new Error(`reference cycle at ${name}`);
  seen.add(name);
  const v = raw.get(name);
  if (v === undefined) throw new Error(`unknown colour token ${name}`);
  const value = typeof v === 'string' ? v : v[theme];
  if (typeof value !== 'string') throw new Error(`token ${name} has no ${theme} value`);
  const ref = value.match(/^\{([a-z0-9-]+)\}$/);
  return ref ? resolve(ref[1], theme, seen) : value.toLowerCase();
}

const colors = {};
for (const theme of themes) {
  colors[theme] = {};
  for (const name of raw.keys()) colors[theme][name] = resolve(name, theme);
}

// ---------------------------------------------------------------- type
const families = { ui: 'ui', learn: 'learn' };
const typeStyles = {};
for (const group of tokens.type.groups) {
  for (const s of group.styles) {
    const fontSize = px(s.fontSize);
    const ls = s.letterSpacing ? String(s.letterSpacing) : null;
    let letterSpacing = 0;
    if (ls && ls.endsWith('em')) letterSpacing = Math.round(parseFloat(ls) * fontSize * 100) / 100;
    else if (ls && ls.endsWith('px')) letterSpacing = px(ls);
    typeStyles[s.name] = {
      family: families[group.family] ?? 'ui',
      fontSize,
      lineHeight: px(s.lineHeight),
      weight: Number(s.fontWeight),
      letterSpacing,
      uppercase: s.name === 'overline',
    };
  }
}

// ---------------------------------------------------------------- spacing, radius, size
const space = {};
for (const t of tokens.spacing.tokens) space[t.name.replace('space-', '')] = px(t.value);
const radius = {};
for (const t of tokens.radius.tokens) radius[t.name.replace('radius-', '')] = px(t.value);
const size = {};
for (const t of tokens.size.tokens) size[t.name] = px(t.value);

// ---------------------------------------------------------------- shadows
function parseShadowList(v) {
  // "0 4px 0 #7f8ca6" or "0 1px 2px #141c2e0f, 0 4px 14px #141c2e0d" or "0 0 0 3px #fff, 0 0 0 6px #1e6bf0"
  return v.split(/,\s*(?=-?\d)/).map((part) => {
    const bits = part.trim().split(/\s+/);
    const color = bits.pop();
    const nums = bits.map((b) => (b === '0' ? 0 : px(b)));
    const [x = 0, y = 0, blur = 0, spread = 0] = nums;
    return { x, y, blur, spread, color: color.toLowerCase() };
  });
}
const shadow = {};
for (const t of tokens.shadow.tokens) {
  shadow[t.name] = {};
  for (const theme of themes) {
    const v = typeof t.value === 'string' ? t.value : t.value[theme];
    shadow[t.name][theme] = parseShadowList(v);
  }
}

const header = (src) =>
  `// GENERATED by scripts/gen-design.mjs from ${src}. Do not edit by hand.\n` +
  `// This file is exempt from the colour-literal lint rule because it *is* the token source.\n\n`;

const tokensTs =
  header('design-system/tokens.json') +
  `export const designSystemVersion = ${JSON.stringify(tokens.version)};\n\n` +
  `export const colors = ${JSON.stringify(colors, null, 2)} as const;\n\n` +
  `export type ThemeName = keyof typeof colors;\n` +
  `export type ColorToken = keyof (typeof colors)['light'];\n\n` +
  `export const typeStyles = ${JSON.stringify(typeStyles, null, 2)} as const;\n\n` +
  `export type TypeStyle = keyof typeof typeStyles;\n\n` +
  `export const space = ${JSON.stringify(space, null, 2)} as const;\n\n` +
  `export const radius = ${JSON.stringify(radius, null, 2)} as const;\n\n` +
  `export const size = ${JSON.stringify(size, null, 2)} as const;\n\n` +
  `export const shadow = ${JSON.stringify(shadow, null, 2)} as const;\n`;

const artTs =
  header('design-system/art.json') +
  `export type ArtElement = readonly [tag: 'path' | 'circle' | 'rect', attrs: Readonly<Record<string, string | number | boolean>>];\n\n` +
  `export const icons = ${JSON.stringify(art.icons)} as const satisfies Record<string, readonly ArtElement[]>;\n\n` +
  `export const colorIcons = ${JSON.stringify(art.colorIcons)} as const satisfies Record<string, readonly ArtElement[]>;\n\n` +
  `/** Pip's poses: SVG inner markup for viewBox 0 0 180 180, drawn inside translate(10 12). */\n` +
  `export const pipPoses = ${JSON.stringify(art.pip, null, 2)} as const;\n`;

mkdirSync(join(root, 'src/design'), { recursive: true });
writeFileSync(join(root, 'src/design/tokens.generated.ts'), tokensTs);
writeFileSync(join(root, 'src/design/art.generated.ts'), artTs);
console.log(
  `design: ${Object.keys(colors.light).length} colours × 2 themes, ${Object.keys(typeStyles).length} type styles, ` +
    `${Object.keys(art.icons).length} icons, ${Object.keys(art.colorIcons).length} colour icons, ${Object.keys(art.pip).length} poses`,
);
